#include "input/input.h"
#include <cmath>

// Generated by the editor into the project (src/p64/inputMap.cpp).
namespace P64::Input
{
  extern const ActionDef ACTIONS[];
  extern const char* const ACTION_NAMES[];
  extern const uint8_t ACTION_COUNT;
}

namespace
{
  using namespace P64::Input;

  constexpr uint32_t PORT_COUNT = 4;

  constexpr uint32_t DPAD_BITS  = BIND_D_UP | BIND_D_DOWN | BIND_D_LEFT | BIND_D_RIGHT;
  constexpr uint32_t CBTN_BITS  = BIND_C_UP | BIND_C_DOWN | BIND_C_LEFT | BIND_C_RIGHT;
  constexpr uint32_t STICK_BITS = BIND_STICK_UP | BIND_STICK_DOWN | BIND_STICK_LEFT | BIND_STICK_RIGHT;

  struct PortState
  {
    joypad_inputs_t inputs{};
    uint32_t digital{};  // Bind bits of the physical buttons held this frame
    uint32_t held{};     // action bits held this frame
    uint32_t heldPrev{}; // action bits held last frame
    float holdTime[MAX_ACTIONS]{};
  };

  PortState ports[PORT_COUNT]{};
  float lastDeltaTime{0.0f};

  uint32_t digitalBits(const joypad_buttons_t &b)
  {
    uint32_t r = 0;
    if(b.a)       r |= BIND_A;
    if(b.b)       r |= BIND_B;
    if(b.z)       r |= BIND_Z;
    if(b.start)   r |= BIND_START;
    if(b.l)       r |= BIND_L;
    if(b.r)       r |= BIND_R;
    if(b.d_up)    r |= BIND_D_UP;
    if(b.d_down)  r |= BIND_D_DOWN;
    if(b.d_left)  r |= BIND_D_LEFT;
    if(b.d_right) r |= BIND_D_RIGHT;
    if(b.c_up)    r |= BIND_C_UP;
    if(b.c_down)  r |= BIND_C_DOWN;
    if(b.c_left)  r |= BIND_C_LEFT;
    if(b.c_right) r |= BIND_C_RIGHT;
    return r;
  }

  // Stick directions past `threshold`, as BIND_STICK_* bits
  uint32_t stickBits(const joypad_inputs_t &in, int threshold)
  {
    uint32_t r = 0;
    if(in.stick_y >  threshold) r |= BIND_STICK_UP;
    if(in.stick_y < -threshold) r |= BIND_STICK_DOWN;
    if(in.stick_x < -threshold) r |= BIND_STICK_LEFT;
    if(in.stick_x >  threshold) r |= BIND_STICK_RIGHT;
    return r;
  }

  StickValue analogStick(const ActionDef &def, const joypad_inputs_t &in)
  {
    float x = (float)in.stick_x;
    float y = (float)in.stick_y;
    float dist = sqrtf(x*x + y*y);
    float deadzone = (float)def.deadzone;
    float range = (float)def.range;
    if(dist <= deadzone || dist < 0.0001f)return {};

    float mag = (range > deadzone) ? (dist - deadzone) / (range - deadzone) : 1.0f;
    mag = fminf(mag, 1.0f);
    if(def.curve > 0.0f && def.curve != 1.0f)mag = powf(mag, def.curve);

    float scale = mag / dist;
    return {x * scale, y * scale, mag};
  }

  // D-pad / C-buttons as a direction, diagonals normalized to length 1
  StickValue digitalStick(uint32_t binds, uint32_t digital)
  {
    float x = 0.0f, y = 0.0f;
    uint32_t active = binds & digital;
    if(active & (BIND_D_UP    | BIND_C_UP))    y += 1.0f;
    if(active & (BIND_D_DOWN  | BIND_C_DOWN))  y -= 1.0f;
    if(active & (BIND_D_LEFT  | BIND_C_LEFT))  x -= 1.0f;
    if(active & (BIND_D_RIGHT | BIND_C_RIGHT)) x += 1.0f;
    if(x == 0.0f && y == 0.0f)return {};
    if(x != 0.0f && y != 0.0f) {
      constexpr float INV_SQRT2 = 0.70710678f;
      x *= INV_SQRT2;
      y *= INV_SQRT2;
    }
    return {x, y, 1.0f};
  }

  StickValue evalStick(const ActionDef &def, const PortState &p)
  {
    StickValue res{};
    if(def.binds & STICK_BITS)res = analogStick(def, p.inputs);
    if(def.binds & (DPAD_BITS | CBTN_BITS)) {
      StickValue dig = digitalStick(def.binds, p.digital);
      if(dig.mag > res.mag)res = dig;
    }
    return res;
  }

  bool evalHeld(const ActionDef &def, const PortState &p)
  {
    if(def.type == ActionType::STICK) {
      return evalStick(def, p).mag > 0.0f;
    }
    uint32_t active = p.digital;
    if(def.binds & STICK_BITS)active |= stickBits(p.inputs, def.threshold);
    return (def.binds & active) != 0;
  }

  inline bool valid(uint8_t action, joypad_port_t port) {
    return action < ACTION_COUNT && action < MAX_ACTIONS && (uint32_t)port < PORT_COUNT;
  }
}

void P64::Input::update(float deltaTime)
{
  lastDeltaTime = deltaTime;
  uint32_t count = ACTION_COUNT < MAX_ACTIONS ? ACTION_COUNT : MAX_ACTIONS;

  for(uint32_t port = 0; port < PORT_COUNT; ++port)
  {
    auto &p = ports[port];
    p.heldPrev = p.held;
    p.held = 0;

    if(!joypad_is_connected((joypad_port_t)port)) {
      p.inputs = {};
      p.digital = 0;
      for(uint32_t i = 0; i < count; ++i)p.holdTime[i] = 0.0f;
      continue;
    }

    p.inputs = joypad_get_inputs((joypad_port_t)port);
    p.digital = digitalBits(p.inputs.btn);

    for(uint32_t i = 0; i < count; ++i)
    {
      if(evalHeld(ACTIONS[i], p)) {
        p.held |= 1u << i;
        p.holdTime[i] += deltaTime;
      } else {
        p.holdTime[i] = 0.0f;
      }
    }
  }
}

bool P64::Input::held(uint8_t action, joypad_port_t port)
{
  if(!valid(action, port))return false;
  return (ports[port].held >> action) & 1;
}

bool P64::Input::pressed(uint8_t action, joypad_port_t port)
{
  if(!valid(action, port))return false;
  const auto &p = ports[port];
  return ((p.held & ~p.heldPrev) >> action) & 1;
}

bool P64::Input::released(uint8_t action, joypad_port_t port)
{
  if(!valid(action, port))return false;
  const auto &p = ports[port];
  return ((~p.held & p.heldPrev) >> action) & 1;
}

bool P64::Input::repeated(uint8_t action, joypad_port_t port, float delay, float rate)
{
  if(!valid(action, port))return false;
  if(pressed(action, port))return true;
  if(!held(action, port) || rate <= 0.0f)return false;

  float t = ports[port].holdTime[action] - delay;
  float tPrev = t - lastDeltaTime;
  if(t < 0.0f)return false;
  if(tPrev < 0.0f)return true; // crossed the initial delay this frame
  return floorf(t / rate) != floorf(tPrev / rate);
}

float P64::Input::heldTime(uint8_t action, joypad_port_t port)
{
  if(!valid(action, port))return 0.0f;
  return ports[port].holdTime[action];
}

P64::Input::StickValue P64::Input::stick(uint8_t action, joypad_port_t port)
{
  if(!valid(action, port))return {};
  const auto &def = ACTIONS[action];
  if(def.type == ActionType::STICK) {
    return evalStick(def, ports[port]);
  }
  return {0.0f, 0.0f, held(action, port) ? 1.0f : 0.0f};
}

uint32_t P64::Input::getActionCount()
{
  return ACTION_COUNT;
}

const char* P64::Input::getActionName(uint8_t action)
{
  return action < ACTION_COUNT ? ACTION_NAMES[action] : "";
}
